#!/usr/bin/env python3
"""Build the user review: official service brands, no datasets, MCP-level targets."""
import argparse,base64,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent

def read(path,default):
    return json.loads(path.read_text()) if path and path.exists() else default

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--output',type=Path,default=ROOT/'review.html')
    parser.add_argument('--drafts',type=Path)
    parser.add_argument('--trials',type=Path)
    parser.add_argument('--apps-evidence',type=Path,help='Accepted for legacy callers; scene agents are out of scope.')
    parser.add_argument('--native-evidence',type=Path)
    parser.add_argument('--e2e-evidence',type=Path)
    args=parser.parse_args()
    rows=read(ROOT/'catalog/coverage.json',{})['services']
    drafts=read(args.drafts,{})
    trials={r['service']:r for r in read(args.trials,{}).get('services',[])}
    listings=read(ROOT/'listings.json',{})
    parity=read(ROOT/'catalog/mcp-parity.json',{'services':{}})
    icons=read(ROOT/'catalog/official-icons.json',{})
    native=read(args.native_evidence,{})
    e2e=read(args.e2e_evidence,{})
    e2e_services={row['key']:row for row in e2e.get('services',[])}
    overrides=read(ROOT/'catalog/icon-overrides.json',{})
    for row in rows:
        row['icon_data']='data:image/png;base64,'+base64.b64encode((ROOT/row['icon']).read_bytes()).decode()
        row['draft']=drafts.get(row['key'])
        row['listing']=listings.get(row['key'])
        row['trial']=trials.get(row['key'])
        row['mcp']=parity['services'].get(row['key'])
        row['e2e']=e2e_services.get(row['key'])
        row['icon_source']=overrides.get(row['key'],icons[row['key']])
        if row['key']=='suno':row['native_draft']=native
    payload=json.dumps({'services':[r for r in rows if r['service_type']=='Api'],'guides':[r for r in rows if r['service_type']!='Api'],'mcp_revision':parity.get('source_revision'),'e2e_summary':{k:v for k,v in e2e.items() if k!='services'}},ensure_ascii=False).replace('</','<\\/')
    html=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coze · 服务插件审查</title><style>
:root{--ink:#182b43;--muted:#62738a;--line:#dce4ee;--blue:#1768bb;--bg:#f4f6fa}*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;color:var(--ink);background:var(--bg);line-height:1.6}a{color:var(--blue)}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #c7d3e1;background:white;padding:9px 14px;border-radius:9px;color:var(--ink)}.wrap{max-width:1320px;margin:auto;padding:28px 36px}header{background:#122a46;color:white;padding:24px 0 18px}header p{color:#c6d5e5;max-width:1000px}.eyebrow{font-size:12px;letter-spacing:2px;color:#91dde4}h1{font-size:34px;margin:12px 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:25px}.stat{border-top:1px solid #4d627a;padding-top:10px}.stat strong{display:block;font-size:28px}.stat span{font-size:13px;color:#bfd0e2}.notice{background:#fff5dd;border:1px solid #e7d39f;padding:17px 21px;border-radius:12px;margin:24px 0}.notice p{margin:5px 0;color:#695a3a;font-size:14px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;position:sticky;top:0;background:var(--bg);padding:14px 0;z-index:1}.toolbar input{flex:1;min-width:240px}input,select,textarea{border:1px solid #c7d3e1;border-radius:9px;padding:10px 13px;background:white;color:var(--ink)}.count,.muted{font-size:13px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:16px}.card{background:white;border:1px solid var(--line);border-radius:15px;padding:21px;display:flex;flex-direction:column;gap:12px}.head{display:flex;align-items:center;gap:16px}.logo{width:68px;height:68px;object-fit:cover;background:white;border-radius:12px;border:0;padding:0}.head h2{margin:0;font-size:22px;line-height:1.3}.card p{font-size:14px;color:#4a5f78;margin:0}.tags{display:flex;flex-wrap:wrap;gap:7px}.tag{font-size:11px;border-radius:6px;padding:3px 8px;background:#edf3fa;color:#365c7f}.tag.warn{background:#fff0d4;color:#87621b}.tag.good{background:#e2f4ed;color:#23644d}.actions{display:flex;gap:16px;align-items:center;margin-top:auto;font-size:13px}.actions button{color:var(--blue)}h2.section{font-size:22px;margin:35px 0 12px}.guides{display:flex;gap:12px;flex-wrap:wrap}.guides a{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:9px;padding:8px 12px;background:white;text-decoration:none;font-size:13px}.guides img{width:30px;height:30px;object-fit:contain}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{border:1px solid var(--line);background:white;border-radius:12px;padding:20px}.panel h3{font-size:16px;margin:0 0 8px}.panel p{font-size:14px;color:#50637b;margin:0}footer{padding:25px 0;color:var(--muted);font-size:12px}dialog{width:calc(100% - 40px);max-width:980px;max-height:90vh;border:0;border-radius:16px;padding:0;box-shadow:0 20px 100px #11274055}dialog::backdrop{background:#10233799}.top{display:flex;align-items:center;gap:18px;position:sticky;top:0;background:white;padding:22px 28px;border-bottom:1px solid var(--line);z-index:2}.top h2{margin:0}.top button{margin-left:auto}.body{padding:8px 28px 30px}.body h3{font-size:17px;margin:24px 0 8px}.body p{white-space:pre-wrap;font-size:14px}.body ul{padding-left:22px}.status{border-left:3px solid #ddaf45;padding:12px 16px;background:#fff7e5;font-size:14px}pre{white-space:pre-wrap;word-break:break-word;background:#eff3f8;padding:15px;border-radius:9px;font-size:12px;max-height:300px;overflow:auto}.tools{display:grid;grid-template-columns:1fr 1fr;gap:10px}.tool{border:1px solid var(--line);border-radius:9px;padding:12px;min-width:0}.tool strong{font-size:12px;overflow-wrap:anywhere}.tool p{font-size:12px;margin:5px 0}.tool summary{font-size:12px;color:var(--blue);cursor:pointer}.media{max-width:100%;max-height:400px;display:block;margin:12px auto;border-radius:10px}audio{width:100%}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:9px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}textarea{display:block;width:100%;min-height:90px;margin:12px 0}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}.wrap{padding:24px}}@media(max-width:650px){.grid,.two,.tools{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}.wrap{padding:18px}.toolbar{position:static}h1{font-size:27px}.top,.body{padding:16px}}
</style><header><div class="wrap"><div class="eyebrow">COZE · SERVICE PLUGINS · REVIEW REVISION 4</div><h1>按服务上架，按 MCP 能力对齐</h1><p>名称使用服务品牌与空格；品牌图标沿用 Studio / 官方素材并放大适配。Identity Verification、Web Extractor、Localization 使用新设计图标。数据集、Digital Human、Dreamina、AI Chat 已移出。</p><div class="stats"><div class="stat"><strong id="service-count"></strong><span>服务插件</span></div><div class="stat"><strong id="mcp-count"></strong><span>有对应独立 MCP 的服务</span></div><div class="stat"><strong>0</strong><span>数据集 · 本轮已移除</span></div><div class="stat"><strong>未发布</strong><span>正式发布等待 review</span></div></div></div></header><main class="wrap"><div class="notice"><strong>发布前测试仍未通过；名称与图标可继续审查</strong><p>已有 HTTP 草稿作为参照，不以接口数量冒充 MCP 能力对齐。例如 Suno 的目标是线上 tools/list 返回的 42 个 MCP 工具，包含生成、续写、翻唱、分轨、角色管理和查询指引。Suno 与 DeepSeek 只有有限的 Coze 草稿调用证据。用户 OAuth、其余插件调用与发布后 Agent 使用仍需验证。</p><p>本轮未提交商店、未发布新工作区版本。Flux 的旧工作区 v1.0.0 来自此前阶段。</p></div><div class="toolbar"><input id="search" aria-label="搜索插件" placeholder="搜索服务或 MCP 工具，例如 Suno / 续写 / image"><select id="group" aria-label="筛选能力类型"><option value="">全部能力</option></select><button id="export">导出审查意见</button></div><div class="count" id="count"></div><div class="grid" id="grid"></div><h2 class="section">其他服务入口</h2><p class="muted">以下是开发工具或用户自有部署的使用指引，不作为已有云端插件能力宣传。</p><div class="guides" id="guides"></div><h2 class="section">测试与连接状态</h2><div class="notice" id="e2e-gate"></div><div class="two"><div class="panel"><h3>已有真实测试</h3><p>初始四项有 Coze 调用证据。后来 23 项直接 API 用例中，18 项获得完整文本或可访问成品；消耗 26.81514 Credits，按最高名义包价约 $4.69，测试凭证已提前停用。它们不等于原生 MCP 插件已通过验证。</p></div><div class="panel"><h3>仍需完成</h3><p>Hailuo、Luma、本地化调用失败；Wan、Maestro 成品链接不可访问。原生 MCP 的授权、工具同步、完整参数与实际调用需要验证。部分服务只有 MCP 源码而没有已确认的托管端点。没有独立 MCP 的服务按公开完整 API 能力准备，不虚构对应关系。</p></div></div><footer>2026-10-05 · 数据集不在本轮范围 · 品牌图标保留官方素材；通用服务图标按审查意见重新设计 · 审查意见仅保存在本机，不触发发布。</footer></main><dialog id="detail"><div class="top" id="top"></div><div class="body" id="body"></div></dialog><script>
const data=PAYLOAD,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let decisions={};try{decisions=JSON.parse(localStorage.getItem('coze-service-review-v3')||'{}')}catch(e){}let current='';
const e2eLabels={pass:'Coze 实际调用通过',blocked_form:'Coze 表单阻塞',not_run:'Coze 未实测'};
$('e2e-gate').innerHTML=data.e2e_summary.active_api_plugins?`<strong>发布门禁：${data.e2e_summary.coze_real_call_passed} / ${data.e2e_summary.active_api_plugins} 项 Coze 实际调用通过</strong><p>已核对 ${data.e2e_summary.mcp_metadata_live} 个在线 MCP 工具清单，${data.e2e_summary.mcp_readonly_passed} 项免费信息工具调用成功；用户授权与发布后 Agent 调用尚未通过。累计测试消耗 ${Number(data.e2e_summary.credits_used_total).toFixed(4)} / ${data.e2e_summary.budget_credit_cap} Credits。<a href="./e2e-v4/launch-gate.json">查看逐项验收结果</a>。</p>`:'';
const trialLabels={verified_text_response:'API 文本已验证',verified_extraction:'API 提取结果已验证',media_url_verified:'API 成品链接可访问',media_url_needs_check:'成品访问受阻',failed:'调用失败',pending_or_no_usable_result:'暂无可用结果'};
$('service-count').textContent=data.services.length;$('mcp-count').textContent=data.services.filter(r=>r.mcp?.mcp).length;
$('group').innerHTML+=[...new Set(data.services.map(r=>r.group))].map(g=>`<option>${esc(g)}</option>`).join('');
function render(){const q=$('search').value.toLowerCase(),g=$('group').value;const rows=data.services.filter(r=>(!g||r.group===g)&&(!q||JSON.stringify([r.name,r.title,r.brief,r.mcp?.tools]).toLowerCase().includes(q)));$('count').textContent=`显示 ${rows.length} / ${data.services.length} 个服务插件。打开详情审查名称图标、上架文案和逐项 MCP 能力。`;$('grid').innerHTML=rows.map(r=>`<article class="card"><div class="head"><img class="logo" src="${r.icon_data}" alt="${esc(r.name)} 图标"><div><h2>${esc(r.name)}</h2><div class="muted">${esc(r.group)}</div></div></div><p>${esc(r.brief)}</p><div class="tags"><span class="tag">${r.mcp?.mcp?`目标：${r.mcp.mcp_tool_count} 个 MCP 工具`:'按完整公开 API 准备'}</span><span class="tag warn">${r.mcp?.mcp?'MCP 对齐待验证':'无对应独立 MCP'}</span>${r.draft?.revision==='2026-10-05-v3-full-frame-spaced-names'&&r.draft?.name===r.name&&r.draft?.icon_saved?'<span class="tag good">名称与图标已同步</span>':'<span class="tag warn">后台元数据待同步</span>'}</div>${r.e2e?`<div class="muted">${esc(e2eLabels[r.e2e.coze_real_call]||r.e2e.coze_real_call)}</div>`:''}${r.trial?`<div class="muted">${esc(trialLabels[r.trial.status]||r.trial.status)}</div>`:''}<div class="actions"><button data-key="${r.key}">审查插件</button><a target="_blank" rel="noreferrer" href="${esc(r.source_url)}">服务页 ↗</a></div></article>`).join('');document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>open(b.dataset.key));}
function open(key){current=key;const r=data.services.find(r=>r.key===key),m=r.mcp,l=r.listing,d=decisions[key]||{};$('top').innerHTML=`<img class="logo" src="${r.icon_data}" alt=""><h2>${esc(r.name)}</h2><button onclick="document.getElementById('detail').close()">关闭</button>`;$('body').innerHTML=`<h3>名字、图标和文案</h3><p><strong>${esc(r.name)}</strong>\n${esc(r.brief)}</p><p>${esc(l.about)}</p><p class="muted">图标来源：${esc(r.icon_source.source)}${r.icon_source.url?` · <a href="${esc(r.icon_source.url)}" target="_blank">原始官方素材</a>`:''}。已按图标框尺寸规范化。</p><h3>使用场景</h3><ul>${l.scenarios.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Coze 草稿状态</h3><div class="status">${r.draft?`<a href="${esc(r.draft.url)}" target="_blank">打开 HTTP 草稿</a>：当前记录 ${r.draft.tool_count??'待核对'} 个工具。此数量不是 MCP 对齐证明。`:'未加载草稿证据。'}${r.native_draft?.url?`<br><a href="${esc(r.native_draft.url)}" target="_blank">打开原生 MCP 草稿</a>：Suno 已在 Coze 核对 42 个工具；授权与完整调用仍未通过。`:''}</div>${r.draft?.import_scope?`<p>${esc(r.draft.import_scope)}</p>`:''}<h3>MCP 能力基准</h3>${m?.mcp?`<p>对应 ${esc(m.mcp)} MCP，${m.benchmark_source==='live tools/list'?'线上 tools/list 返回':'源码注册'} <strong>${m.mcp_tool_count}</strong> 个工具。参考源码版本：${esc(data.mcp_revision?.slice(0,12))}。</p><p>${m.endpoint?`托管端点：<a target="_blank" href="${esc(m.endpoint)}">${esc(m.endpoint)}</a>`:'没有已确认的托管端点，需先准备 Coze 可连接的传输。'}</p><div class="status">这些是必须对齐的 MCP 能力，不代表当前 Coze 已全部可用。模型查询、格式指引、批量结果和管理操作同样纳入，不只覆盖生成接口。</div><div class="tools">${m.tools.map(t=>`<article class="tool"><strong>${esc(t.name)}</strong><p>${esc((t.description||'').split('\n')[0])}</p><details><summary>参数与能力说明</summary><p>${esc(t.description)}</p><pre>${esc(JSON.stringify(t.input_schema||{parameters:t.parameters,defaults:t.defaults},null,2))}</pre></details></article>`).join('')}</div>`:`<p>${esc(m?.note||'没有独立 MCP 基准，按公开服务合同准备。')}</p>`}<h3>发布前 E2E 状态</h3><div class="status">${r.e2e?`${esc(e2eLabels[r.e2e.coze_real_call]||r.e2e.coze_real_call)}。${esc(r.e2e.coze_evidence||'')} 用户 OAuth 授权和发布后 Agent 使用尚未通过。`:'未加载本轮 E2E 证据。'}</div><h3>现有 HTTP 接口覆盖</h3><table><tr><th>接口</th><th>状态</th></tr>${r.operations.map(o=>`<tr><td>${esc(o.method)} ${esc(o.path)}</td><td>${esc(o.disposition)}${o.reason?` · ${esc(o.reason)}`:''}</td></tr>`).join('')}</table>${r.trial?`<h3>已有 API 实测</h3><div class="status">${esc(trialLabels[r.trial.status]||r.trial.status)}。这是直接 API 测试，不能替代 MCP / Coze 运行验证。</div>${r.trial.launch_blocker?`<p>${esc(r.trial.launch_blocker)}</p>`:''}${r.trial.assistant_text?`<p>${esc(r.trial.assistant_text)}</p>`:''}${(r.trial.media||[]).filter(x=>x.http_status===200).map(x=>(x.content_type||'').includes('image')?`<img class="media" src="${esc(x.url)}" loading="lazy" alt="实测成品">`:(x.content_type||'').includes('audio')?`<audio controls preload="none" src="${esc(x.url)}"></audio>`:`<video class="media" controls preload="none" src="${esc(x.url)}"></video>`).join('')}`:''}<h3>审查意见</h3><p class="muted">只保存在本机；不会触发发布。</p><select id="choice"><option value="pending">待审查</option><option value="keep">保留名字图标文案</option><option value="change">需要修改</option><option value="hold">暂缓上线</option></select><textarea id="note" aria-label="审查备注" placeholder="名字、图标、文案或能力的修改意见">${esc(d.note||'')}</textarea><button id="save">保存意见</button><span class="muted" id="saved"></span>`;$('choice').value=d.choice||'pending';$('save').onclick=()=>{decisions[current]={choice:$('choice').value,note:$('note').value,updated_at:new Date().toISOString()};localStorage.setItem('coze-service-review-v3',JSON.stringify(decisions));$('saved').textContent=' 已保存在本机'};$('detail').showModal();}
$('guides').innerHTML=data.guides.map(r=>`<a href="${esc(r.source_url)}" target="_blank"><img src="${r.icon_data}" alt="">${esc(r.title)}</a>`).join('');$('search').oninput=render;$('group').onchange=render;$('export').onclick=()=>{let u=URL.createObjectURL(new Blob([JSON.stringify({revision:3,publication_authorized:false,decisions},null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='coze-service-review-v3.json';a.click();URL.revokeObjectURL(u)};render();</script></html>'''.replace('PAYLOAD',payload)
    args.output.parent.mkdir(parents=True,exist_ok=True)
    args.output.write_text(html)
    print(args.output)

if __name__=='__main__':main()
